-- Registration attempts, payment columns and payment events (docs/plans/PAYMENTS-PLAN.md section 4.2, M1).
-- Generated by Prisma, then this guard was added by hand. The new NOT NULL columns (payments.pending_registration_id,
-- payments.gateway_account, the attempt's email/phone/name) have no meaningful backfill, so this migration refuses a
-- database that already holds payments or pending registrations. It never deletes anything (owner rule).
-- Prisma runs the file as one transaction: when the guard fires, nothing changed; the migration is recorded as failed
-- and must be marked rolled back before the next try (docs/RUNBOOK.md section 0, "Payments migration on an old dev
-- database").
DO $$
DECLARE
  n_payments bigint;
  n_pending bigint;
BEGIN
  SELECT count(*) INTO n_payments FROM "payments";
  SELECT count(*) INTO n_pending FROM "pending_registrations";
  IF n_payments > 0 OR n_pending > 0 THEN
    RAISE EXCEPTION 'payments_registration: the database holds % payment(s) and % pending registration(s); this migration needs both tables empty. Dev database: remove the dev-fixture payments (pnpm --filter @sirat/api db:fixtures:dev --clean), mark this migration rolled back, migrate again, then reload the fixtures (docs/RUNBOOK.md section 0). Any other database: stop and ask the owner; never delete rows by hand.', n_payments, n_pending;
  END IF;
END
$$;

-- CreateEnum
CREATE TYPE "RegistrationAttemptStatus" AS ENUM ('open', 'completed', 'abandoned', 'conflict');

